const data = $input.first().json || {};
const addons = (data._embedded && Array.isArray(data._embedded.addons)) ? data._embedded.addons : [];
return addons
  .map((a) => {
    const emb = a._embedded || {};
    const dist = emb.distribution || {};
    const rev = emb.reviews || {};
    const vendor = emb.vendor || {};
    const altHref = a._links?.alternate?.href || "";
    const vendorHref = vendor._links?.alternate?.href || "";
    const avgStars = rev.averageStars != null ? Number(Number(rev.averageStars).toFixed(2)) : null;
    const installs = Number(dist.totalInstalls || 0);
    return {
      json: {
        addonKey: a.key,
        name: a.name,
        tagLine: a.tagLine || "",
        vendorName: vendor.name || null,
        vendorUrl: vendorHref ? `https://marketplace.atlassian.com${vendorHref}` : null,
        totalInstalls: installs,
        totalUsers: dist.totalUsers ?? null,
        averageStars: avgStars,
        reviewCount: rev.count || 0,
        highInstallChurnTarget: installs >= 500 && (avgStars === null || avgStars < 4.2),
        marketplaceUrl: altHref ? `https://marketplace.atlassian.com${altHref}` : null,
      },
    };
  })
  .sort((a, b) => Number(b.json.highInstallChurnTarget) - Number(a.json.highInstallChurnTarget) || b.json.totalInstalls - a.json.totalInstalls);
